package com.clavis.reader;
import android.app.*;import android.content.*;import android.net.Uri;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
/** Curated starters, seeded once; removing a subscription is respected on future launches. */
final class FeedCatalog {
 static JSONArray catalog(Context c)throws Exception{try(InputStream in=c.getAssets().open("rss/catalog.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int count;while((count=in.read(buffer))!=-1)out.write(buffer,0,count);return new JSONArray(new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8));}}
 static synchronized void seed(Context c){android.content.SharedPreferences prefs=c.getSharedPreferences("rss_feeds",0);if(prefs.getBoolean("starter_v1",false))return;try{ArrayList<FeedStore.Feed> feeds=FeedStore.load(c);JSONArray entries=catalog(c);for(int n=0;n<entries.length();n++){JSONObject source=entries.getJSONObject(n);if(!source.optBoolean("preload"))continue;boolean exists=false;for(FeedStore.Feed f:feeds)if(f.url.equals(source.getString("url"))&&f.kind.equals(source.getString("kind")))exists=true;if(exists)continue;try(InputStream input=c.getAssets().open(source.getString("asset"))){FeedStore.Feed feed=FeedStore.parse(input,source.getString("url"));feed.kind=source.getString("kind");feed.title=source.getString("title");feed.updated=System.currentTimeMillis();feeds.add(feed);}}FeedStore.save(c,feeds);prefs.edit().putBoolean("starter_v1",true).apply();}catch(Exception e){android.util.Log.e("ClavisRSS","Could not load starter feeds",e);}}
 static String label(String kind){return kind.equals("Journals")?"Articles":kind;}
 static void browse(MainActivity a,String kind){
  LinearLayout panel=a.column();panel.setPadding(a.dp(18),a.dp(8),a.dp(18),a.dp(12));
  EditText search=new EditText(a);search.setSingleLine();search.setHint("Publisher, website or topic");search.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);panel.addView(search);
  LinearLayout rows=a.column();ScrollView scroll=new ScrollView(a);scroll.addView(rows);panel.addView(scroll,new LinearLayout.LayoutParams(-1,a.dp(280)));
  final AlertDialog[] directory={null};
  TextView online=a.button("Search "+label(kind).toLowerCase(Locale.ROOT)+" online",()->{String query=search.getText().toString().trim();if(query.isEmpty()){search.setError("Enter a publisher, website or topic");return;}directory[0].dismiss();if(kind.equals("Podcasts"))searchPodcasts(a,query);else searchSources(a,query,kind);});panel.addView(online);panel.addView(a.button("Add custom RSS URL",()->{directory[0].dismiss();FeedScreens.add(a,kind);}));
  AlertDialog dialog=new AppDialog.Builder(a).setTitle("Browse "+label(kind).toLowerCase(Locale.ROOT)+" sources").setView(panel).setNegativeButton("Close",null).create();directory[0]=dialog;
  Runnable render=()->{rows.removeAllViews();try{JSONArray entries=catalog(a);for(int n=0;n<entries.length();n++){JSONObject source=entries.getJSONObject(n);if(!source.getString("kind").equals(kind)||!source.getString("title").toLowerCase(Locale.ROOT).contains(search.getText().toString().toLowerCase(Locale.ROOT)))continue;sourceRow(a,rows,source,dialog);}if(rows.getChildCount()==0)rows.addView(a.text("No matching starter sources. Search online for more.",14,MainActivity.MUTED,false));}catch(Exception e){rows.addView(a.text("Source directory could not be opened",14,MainActivity.MUTED,false));}};
  search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){render.run();}public void afterTextChanged(Editable text){}});
  search.setOnEditorActionListener((view,action,event)->{if(action==android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH){online.performClick();return true;}return false;});render.run();dialog.show();
 }
 static void searchSources(MainActivity a,String query,String kind){
  java.util.concurrent.atomic.AtomicBoolean cancelled=new java.util.concurrent.atomic.AtomicBoolean();
  ProgressDialog progress=new ProgressDialog(a);progress.setMessage("Searching "+label(kind).toLowerCase(Locale.ROOT)+" sources…");progress.setCancelable(true);progress.setOnCancelListener(d->cancelled.set(true));progress.show();
  a.io.execute(()->{try{JSONArray results=FeedDiscovery.search(query,kind);a.runOnUiThread(()->{if(a.isDestroyed()||a.isFinishing()||cancelled.get())return;progress.dismiss();showSourceResults(a,query,kind,results);});}
   catch(Exception e){a.runOnUiThread(()->{if(a.isDestroyed()||a.isFinishing()||cancelled.get())return;progress.dismiss();new AppDialog.Builder(a).setTitle(label(kind)+" search").setMessage("Could not search online. Check your connection or try again.").setPositiveButton("Try again",(d,n)->searchSources(a,query,kind)).setNegativeButton("Close",null).show();});}});
 }
 static AlertDialog showSourceResults(MainActivity a,String query,String kind,JSONArray results){
  LinearLayout rows=a.column();rows.setPadding(a.dp(18),a.dp(12),a.dp(18),a.dp(12));ScrollView scroll=new ScrollView(a);scroll.addView(rows);
  AlertDialog dialog=new AppDialog.Builder(a).setTitle(label(kind)+" results").setView(scroll).setNegativeButton("Close",null).create();
  rows.addView(a.text("Sources matching “"+query+"”. Tap a source to add it.",14,MainActivity.MUTED,false));a.space(rows,12);
  if(results.length()==0){rows.addView(a.text("No RSS sources found. Try a publisher name, a website, or another topic.",14,MainActivity.INK,false));a.space(rows,12);}
  try{for(int n=0;n<results.length();n++)sourceRow(a,rows,results.getJSONObject(n),dialog);}catch(Exception e){rows.addView(a.text("Some results could not be displayed. Try another search.",14,MainActivity.MUTED,false));}
  rows.addView(a.button("Add custom RSS URL",()->{dialog.dismiss();FeedScreens.add(a,kind);}));
  TextView credit=a.button("Source search by Feedly",()->a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://feedly.com"))));credit.setTextSize(12);rows.addView(credit);dialog.show();return dialog;
 }
 static void sourceRow(MainActivity a,LinearLayout rows,JSONObject source,Dialog dialog)throws Exception{String title=source.getString("title"),kind=source.getString("kind"),url=source.getString("url");boolean subscribed=false;for(FeedStore.Feed feed:FeedStore.load(a))if(feed.kind.equals(kind)&&feed.url.equals(url))subscribed=true;final boolean exists=subscribed;TextView choice=a.button(title+(subscribed?"  ·  Added":"  +"),()->{if(exists){dialog.dismiss();FeedScreens.show(a,kind);return;}ProgressDialog progress=new ProgressDialog(a);progress.setMessage("Adding "+title+"…");progress.setCancelable(false);progress.show();a.io.execute(()->{try{FeedStore.Feed feed=FeedStore.download(url,kind);feed.title=title;FeedStore.put(a,feed);a.runOnUiThread(()->{if(a.isDestroyed())return;progress.dismiss();dialog.dismiss();FeedScreens.show(a,kind);});}catch(Exception e){a.runOnUiThread(()->{if(a.isDestroyed())return;progress.dismiss();new AppDialog.Builder(a).setTitle("RSS source").setMessage(e.getMessage()).setPositiveButton("Close",null).show();});}});});choice.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);choice.setTextSize(14);rows.addView(choice,new LinearLayout.LayoutParams(-1,-2));a.space(rows,8);}
 static void searchPodcasts(MainActivity a,String query){ProgressDialog progress=new ProgressDialog(a);progress.setMessage("Searching podcasts…");progress.setCancelable(false);progress.show();a.io.execute(()->{try{String url="https://itunes.apple.com/search?media=podcast&entity=podcast&limit=25&term="+Uri.encode(query);JSONObject json=new JSONObject(new String(FeedStore.fetch(url,2*1024*1024),java.nio.charset.StandardCharsets.UTF_8));JSONArray results=json.getJSONArray("results");a.runOnUiThread(()->{if(a.isDestroyed())return;progress.dismiss();LinearLayout rows=a.column();rows.setPadding(a.dp(16),a.dp(8),a.dp(16),a.dp(12));ScrollView scroll=new ScrollView(a);scroll.addView(rows);AlertDialog dialog=new AppDialog.Builder(a).setTitle("Podcast results").setView(scroll).setNegativeButton("Close",null).create();try{for(int n=0;n<results.length();n++){JSONObject result=results.getJSONObject(n);String feed=FeedStore.web(result.optString("feedUrl"));if(!feed.startsWith("https://"))continue;JSONObject source=new JSONObject().put("kind","Podcasts").put("title",result.optString("collectionName","Podcast")).put("url",feed);sourceRow(a,rows,source,dialog);}if(rows.getChildCount()==0)rows.addView(a.text("No RSS podcasts found",14,MainActivity.MUTED,false));dialog.show();}catch(Exception e){new AppDialog.Builder(a).setMessage("Could not display search results").setPositiveButton("Close",null).show();}});}catch(Exception e){a.runOnUiThread(()->{if(a.isDestroyed())return;progress.dismiss();new AppDialog.Builder(a).setTitle("Podcast search").setMessage(e.getMessage()).setPositiveButton("Close",null).show();});}});}
}
